var throttle = function(fun,delay){
var perv = Date.now();
return function(){
var context = this;
var now = Date.now();
if (now-perv &gt;= delay){
fun.apply(context,arguments)
prev = Date.now();
}
}
}
window.addEventListener('scroll',throttle(lazyload,1000))
